             if grid[r][c] not in (0, 8)]
    if not guide:
        return out

    # Get guide colors from top to bottom, one color per horizontal guide band.
    bands = {}
    for r, c, color in guide:
        bands.setdefault(r, []).append((c, color))
    guide_bands = sorted(bands)
    colors = []
    for r in guide_bands:
        colors.append(min(bands[r])[1])

    # Color the 8-shape by its three main horizontal sections.
    rows = [r for r in range(h) if any(v == 8 for v in grid[r])]
    if not rows:
        return out
    top = min(rows)
    bottom = max(rows)
    mid = (top + bottom) // 2

    for r in rows:
        if r <= top + 3:
            color = colors[0]
        elif r <= mid:
            color = colors[min(1, len(colors)-1)]
        else:
            color = colors[min(2, len(colors)-1)]
        for c in range(w):
            if grid[r][c] == 8:
                out[r][c] = color
    return out
